window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aa4d01814f8fcb56"]={"versions": [{"id": "FIG-aa4d01814f8fcb56", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext der AUTOSAR-Methodik (SPEM 2.0-Profilierung). Das Diagramm spezifiziert die konzeptionelle Einbettung der <em>Work Product Definition</em> sowie deren Beziehung zur AUTOSAR-Metamodell-Struktur (<em>ARPackage::ARElement</em>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Work Product Definition</strong>: Zentrales Metamodell-Element (dargestellt als SPEM-Work-Product-Dokumentensymbol).\n</li><li><strong>PackageableElement / ARPackage::ARElement</strong>: Metaklasse im Paket <code>ARPackage</code>, dargestellt als zweigeteilter UML-Klassenkasten (kursiv gesetzt als abstraktes Element).\n</li><li><strong>Spezialisierungen / Konkretisierungen</strong>: Ein unbenanntes Dokumentenelement steht in einer Generalisierungsbeziehung (geschlossener, nicht ausgefüllter Pfeilkopf) zur <em>Work Product Definition</em>. Zudem verweist ein Deliverable-Element (Briefsymbol, partiell beschriftet als <code>Deliverable?</code>) über eine Generalisierungsbeziehung auf die <em>Work Product Definition</em>.\n</li><li><strong>«AtpUseMetaModelElement»</strong>: Gestrichelte Abhängigkeitspfeil-Beziehung (Dependency) vom unbenannten Dokumenten-Metamodellelement hin zu <code>PackageableElement / ARPackage::ARElement</code>.\n</li><li><strong>«SPEM_Aggregation»</strong>: Geteilte Aggregation (offene Raute) vom Deliverable-Element zur <em>Work Product Definition</em> mit Ziel-Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der AUTOSAR-Methodikmetamodellierung. Es zeigt keine dynamischen Verhaltensweisen oder zeitlichen Nachrichtensequenzen, sondern strukturelle Vererbungs-, Aggregations- und Stereotypen-Abhängigkeiten zur Definitionszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Werkzeughersteller müssen beachten, dass Work Products in der AUTOSAR-Methodik auf SPEM-Konzepten aufsetzen und über das Stereotyp <code>«AtpUseMetaModelElement»</code> an die paketierbaren Elemente des AUTOSAR-Kernmetamodells (<code>ARElement</code>) angebunden werden. Aggregationen von Teilartefakten zu übergeordneten Lieferobjekten (Deliverables) folgen den SPEM-Aggregationssemantiken mit einer Multiplizität von <code>0..*</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-86c3eb6a0743bdfa", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext der AUTOSAR-Methodik (SPEM 2.0-Profilierung). Das Diagramm spezifiziert die konzeptionelle Einbettung der <em>Work Product Definition</em> sowie deren Beziehung zur AUTOSAR-Metamodell-Struktur (<em>ARPackage::ARElement</em>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Work Product Definition</strong>: Zentrales Metamodell-Element (dargestellt als SPEM-Work-Product-Dokumentensymbol).\n</li><li><strong>PackageableElement / ARPackage::ARElement</strong>: Metaklasse im Paket <code>ARPackage</code>, dargestellt als zweigeteilter UML-Klassenkasten (kursiv gesetzt als abstraktes Element).\n</li><li><strong>Spezialisierungen / Konkretisierungen</strong>: Ein unbenanntes Dokumentenelement steht in einer Generalisierungsbeziehung (geschlossener, nicht ausgefüllter Pfeilkopf) zur <em>Work Product Definition</em>. Zudem verweist ein Deliverable-Element (Briefsymbol, partiell beschriftet als <code>Deliverable?</code>) über eine Generalisierungsbeziehung auf die <em>Work Product Definition</em>.\n</li><li><strong>«AtpUseMetaModelElement»</strong>: Gestrichelte Abhängigkeitspfeil-Beziehung (Dependency) vom unbenannten Dokumenten-Metamodellelement hin zu <code>PackageableElement / ARPackage::ARElement</code>.\n</li><li><strong>«SPEM_Aggregation»</strong>: Geteilte Aggregation (offene Raute) vom Deliverable-Element zur <em>Work Product Definition</em> mit Ziel-Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der AUTOSAR-Methodikmetamodellierung. Es zeigt keine dynamischen Verhaltensweisen oder zeitlichen Nachrichtensequenzen, sondern strukturelle Vererbungs-, Aggregations- und Stereotypen-Abhängigkeiten zur Definitionszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Werkzeughersteller müssen beachten, dass Work Products in der AUTOSAR-Methodik auf SPEM-Konzepten aufsetzen und über das Stereotyp <code>«AtpUseMetaModelElement»</code> an die paketierbaren Elemente des AUTOSAR-Kernmetamodells (<code>ARElement</code>) angebunden werden. Aggregationen von Teilartefakten zu übergeordneten Lieferobjekten (Deliverables) folgen den SPEM-Aggregationssemantiken mit einer Multiplizität von <code>0..*</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-aa4d01814f8fcb56", "to": "FIG-86c3eb6a0743bdfa", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
